import pandas as pd


def run(inputs: dict) -> dict:
    dim = inputs['DIM_PRODUCT'].copy()
    stg = inputs['STG_PRODUCT'].copy()

    # Convert DIM_PRODUCT to list-of-dict so we can mutate rows in place
    # while also appending brand new rows (new versions) to the same list,
    # preserving all historical rows untouched.
    output_rows = dim.to_dict('records')

    # Track the current (is_current == 1) row object per product_id.
    current_state = {}
    for row in output_rows:
        if row.get('is_current') == 1:
            current_state[row['product_id']] = row

    # Sort staged records by product_id, update_date ascending, stable sort
    # (cursor order), WITHOUT deduplication.
    stg_sorted = stg.sort_values(
        by=['product_id', 'update_date'],
        kind='mergesort'
    )

    def _eq(x, y):
        x_na = pd.isna(x)
        y_na = pd.isna(y)
        if x_na and y_na:
            return True
        if x_na or y_na:
            return False
        return x == y

    def attrs_equal(cur_row, s_row):
        return (
            _eq(cur_row['category'], s_row['category']) and
            _eq(cur_row['price_band'], s_row['price_band'])
        )

    for _, s in stg_sorted.iterrows():
        pid = s['product_id']
        cur = current_state.get(pid)

        if cur is None:
            new_row = {
                'product_id': pid,
                'category': s['category'],
                'price_band': s['price_band'],
                'eff_start_date': s['update_date'],
                'eff_end_date': pd.NaT,
                'is_current': 1,
            }
            output_rows.append(new_row)
            current_state[pid] = new_row
        else:
            if not attrs_equal(cur, s):
                # Expire current version
                cur['eff_end_date'] = s['update_date']
                cur['is_current'] = 0

                # Insert new current version
                new_row = {
                    'product_id': pid,
                    'category': s['category'],
                    'price_band': s['price_band'],
                    'eff_start_date': s['update_date'],
                    'eff_end_date': pd.NaT,
                    'is_current': 1,
                }
                output_rows.append(new_row)
                current_state[pid] = new_row
            # else: attributes unchanged -> no-op, no new version created

    out_df = pd.DataFrame(
        output_rows,
        columns=[
            'product_id', 'category', 'price_band',
            'eff_start_date', 'eff_end_date', 'is_current'
        ]
    )

    return {'dim_product_out': out_df}
